package com.sqlapp.swing;

import java.awt.*;
import java.util.function.Consumer;
import javax.swing.*;
import org.fife.ui.rsyntaxtextarea.SyntaxConstants;

/**
 * Read-only generated bytes; edits must regenerate the snapshot before copying.
 */
final class TransferNameMappingPreview extends JPanel {
	private static final long serialVersionUID = 1L;
	final org.fife.ui.rsyntaxtextarea.RSyntaxTextArea text = CodeEditors.create(SyntaxConstants.SYNTAX_STYLE_YAML,
			false);
	final EditorNavigationBar navigation = new EditorNavigationBar(text, false);
	final JButton refresh = new JButton("Refresh preview");
	final JButton copy = new JButton("Copy YAML");
	final JLabel status = new JLabel("Generate a preview to inspect the mapping before saving. No file is written.");
	private final Consumer<String> clipboard;
	private String snapshot;
	private boolean available = true;
	private boolean attempted;

	TransferNameMappingPreview() {
		this(value -> Toolkit.getDefaultToolkit().getSystemClipboard()
				.setContents(new java.awt.datatransfer.StringSelection(value), null));
	}

	TransferNameMappingPreview(Consumer<String> clipboard) {
		super(new BorderLayout(4, 4));
		this.clipboard = java.util.Objects.requireNonNull(clipboard);
		var top = new JPanel(new BorderLayout());
		var actions = new JPanel(new FlowLayout(FlowLayout.LEFT));
		actions.add(refresh);
		actions.add(copy);
		top.add(actions, BorderLayout.NORTH);
		top.add(navigation, BorderLayout.CENTER);
		add(top, BorderLayout.NORTH);
		add(CodeEditors.scroll(text), BorderLayout.CENTER);
		var bottom = new JPanel(new BorderLayout());
		bottom.add(status, BorderLayout.CENTER);
		bottom.add(new EditorPositionLabel(text), BorderLayout.EAST);
		add(bottom, BorderLayout.SOUTH);
		copy.addActionListener(event -> {
			if (!available || snapshot == null)
				return;
			try {
				clipboard.accept(snapshot);
				status.setText("Mapping YAML copied. No file was written; save and review before execution.");
			} catch (RuntimeException failure) {
				status.setText("Copy failed. Retry Copy YAML or select and copy text from the preview.");
			}
		});
		refreshEnabled(true);
	}

	void showSnapshot(String yaml) {
		snapshot = java.util.Objects.requireNonNull(yaml);
		navigation.history.resetWith(() -> text.setText(yaml));
		text.setCaretPosition(0);
		status.setText("Generated YAML; no file written. Save settings and review before execution.");
		refreshEnabled(available);
	}

	void invalidate(String message) {
		snapshot = null;
		attempted = true;
		navigation.history.resetWith(() -> text.setText(""));
		status.setText(message);
		refreshEnabled(available);
	}

	void changed() {
		if (snapshot != null || attempted) {
			invalidate("Names changed. Refresh the preview to inspect the latest YAML.");
			attempted = false;
		}
	}

	void refreshEnabled(boolean enabled) {
		available = enabled;
		copy.setEnabled(enabled && snapshot != null);
		refresh.setEnabled(enabled);
		navigation.setBusy(!enabled);
	}
}
